// Personal fork: card value data, generated by `pnpm value:refresh` (scripts/value/build_values.py).
// Snapshot only — refreshed when a new set comes out, never fetched live.

export type TwoStarKind = 'full_art' | 'trainer' | 'rainbow'

export interface CardValue {
  demand?: number // pokemontcglivetrade trade board: users wanting the card
  supply?: number // pokemontcglivetrade trade board: users offering the card
  wish?: number // pokemon.eleet.dev wishlist count
  offers?: number // pokemon.eleet.dev trade-list count
  // ☆☆ only (community vote Elo from pokemontcglivetrade):
  elo?: number
  adj?: number // vote-adjusted Elo; use this for comparisons
  rank?: number // rank among all ☆☆ cards, 1 = best
  votes?: number
  kind?: TwoStarKind
}

interface ValuesJson {
  generated_at: string
  two_star_count: number
  cards: Record<string, CardValue>
}

const ValuesJsonModule = await import('../../assets/values.json')
const values = ValuesJsonModule.default as ValuesJson

export const valuesGeneratedAt = values.generated_at
export const twoStarCount = values.two_star_count

// Below this many votes a ☆☆ Elo is still settling (typical for a set in its first month)
export const PROVISIONAL_VOTES = 200

export function getCardValue(cardId: string): CardValue | undefined {
  return values.cards[cardId]
}

export function isProvisional(value: CardValue | undefined) {
  return value?.votes !== undefined && value.votes < PROVISIONAL_VOTES
}

/** How sought-after a card is: wishlists per trade-list offer (eleet), else trade-board demand/supply. */
export function demandRatio(value: CardValue | undefined): number {
  if (!value) {
    return 0
  }
  if (value.wish !== undefined && value.offers !== undefined) {
    return value.wish / Math.max(value.offers, 1)
  }
  if (value.demand !== undefined && value.supply !== undefined) {
    return value.demand / Math.max(value.supply, 1)
  }
  return 0
}

/** Single sort key for "most valuable first": ☆☆ adjusted Elo when available, else demand. */
export function valueSortKey(cardId: string): number {
  const value = getCardValue(cardId)
  if (value?.adj !== undefined) {
    return 1_000_000 + value.adj
  }
  return demandRatio(value)
}

export const kindLabel: Record<TwoStarKind, string> = {
  full_art: 'Full art',
  trainer: 'Trainer',
  rainbow: 'Rainbow',
}
